const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const keys={draft:'fakturi:draft',supplier:'fakturi:supplier',history:'fakturi:history',clients:'fakturi:clients'};
const defaults={name:'',address:'',city:'',country:'България',id:'',mol:''};
const money=n=>new Intl.NumberFormat('bg-BG',{style:'currency',currency:'EUR'}).format(Number(n)||0);
const dateBG=s=>{if(!s)return '';const [y,m,d]=s.split('-');return `${d}.${m}.${y}`};
const pad=n=>String(n||'').replace(/\D/g,'').padStart(10,'0');
const getJSON=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
const setJSON=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
let supplier={...defaults,...getJSON(keys.supplier,{})};
let history=getJSON(keys.history,[]);

function values(){const q=+$ ('#quantity').value||0,p=+$('#price').value||0,t=+$('#taxRate').value||0;return {number:pad($('#number').value),date:$('#date').value,clientName:$('#clientName').value.trim(),clientId:$('#clientId').value.trim(),clientMol:$('#clientMol').value.trim(),address1:$('#address1').value.trim(),address2:$('#address2').value.trim(),quantity:q,price:p,taxRate:t,subtotal:q*p,tax:q*t,total:q*(p+t)}}
function calculate(){const d=values();$('#subtotalOut').textContent=money(d.subtotal);$('#taxOut').textContent=money(d.tax);$('#totalOut').textContent=money(d.total);saveDraft()}
function saveDraft(){const data={};$$('#invoiceForm input').forEach(i=>data[i.id]=i.type==='checkbox'?i.checked:i.value);setJSON(keys.draft,data);$('#saveState').textContent='Запазено';clearTimeout(saveDraft.t);saveDraft.t=setTimeout(()=>$('#saveState').textContent='Запазва се автоматично',1300)}
function loadDraft(){const d=getJSON(keys.draft,{});$$('#invoiceForm input').forEach(i=>{if(d[i.id]!==undefined)i.type==='checkbox'?i.checked=d[i.id]:i.value=d[i.id]});if(!$('#date').value)$('#date').value=new Date().toISOString().slice(0,10);if(!$('#number').value)$('#number').value=String((history[0]?.numericNumber||0)+1);calculate()}
function numberUnder1000(n,gender='m'){if(!n)return '';const units={m:['','един','два','три','четири','пет','шест','седем','осем','девет'],f:['','една','две','три','четири','пет','шест','седем','осем','девет'],n:['','едно','две','три','четири','пет','шест','седем','осем','девет']}[gender];const tens=['','десет','двадесет','тридесет','четиридесет','петдесет','шестдесет','седемдесет','осемдесет','деветдесет'];const teens=['десет','единадесет','дванадесет','тринадесет','четиринадесет','петнадесет','шестнадесет','седемнадесет','осемнадесет','деветнадесет'];const hundreds=['','сто','двеста','триста','четиристотин','петстотин','шестстотин','седемстотин','осемстотин','деветстотин'];let a=[],h=Math.floor(n/100),r=n%100;if(h)a.push(hundreds[h]);if(r){if(a.length)a.push('и');if(r<10)a.push(units[r]);else if(r<20)a.push(teens[r-10]);else{a.push(tens[Math.floor(r/10)]);if(r%10)a.push('и',units[r%10])}}return a.join(' ')}
function integerWords(n,gender='m'){if(n===0)return 'нула';let mil=Math.floor(n/1e6),th=Math.floor(n%1e6/1000),rest=n%1000,a=[];if(mil)a.push(mil===1?'един милион':numberUnder1000(mil)+' милиона');if(th)a.push(th===1?'една хиляда':numberUnder1000(th,'f')+' хиляди');if(rest){if(a.length&&(rest<100||rest%100===0))a.push('и');a.push(numberUnder1000(rest,gender))}return a.join(' ').replace('и и','и')}
function amountWords(v){v=Math.round(v*100)/100;const e=Math.floor(v),c=Math.round((v-e)*100);const ew=e===1?'едно евро':e===2?'две евро':`${integerWords(e,'n')} евро`;const cw=c===1?'един цент':c===2?'два цента':`${integerWords(c)} цента`;return (ew+' и '+cw).replace(/^./,x=>x.toUpperCase())}
function invoicePage(d,label){const node=$('#invoiceTemplate').content.cloneNode(true),page=node.querySelector('.invoice-sheet');page.querySelector('.recipient-lines').textContent=[d.clientName,d.address1,d.address2,`ЕИК/Булстат: ${d.clientId}`,`МОЛ: ${d.clientMol}`].filter(Boolean).join('\n');page.querySelector('.supplier-lines').textContent=[supplier.name,supplier.address,supplier.city,supplier.country,`ЕИК/Булстат: ${supplier.id}`,`МОЛ: ${supplier.mol}`].join('\n');page.querySelectorAll('.inv-number').forEach(x=>x.textContent=d.number);page.querySelectorAll('.inv-date').forEach(x=>x.textContent=dateBG(d.date));page.querySelector('.copy-label').textContent=label;page.querySelector('.inv-qty').textContent=`${d.quantity.toFixed(2)} бр.`;page.querySelector('.inv-price').textContent=money(d.price);page.querySelector('.inv-subtotal').textContent=money(d.subtotal);page.querySelector('.inv-tax').textContent=money(d.tax);page.querySelectorAll('.inv-total').forEach(x=>x.textContent=money(d.total));page.querySelector('.inv-words').textContent=amountWords(d.total);page.querySelector('.recipient-mol').textContent=d.clientMol;page.querySelector('.supplier-mol').textContent=supplier.mol;return page}
function renderPreview(d,onlyOriginal=false){const pages=$('#invoicePages');pages.innerHTML='';pages.append(invoicePage(d,'ОРИГИНАЛ'));if(!onlyOriginal)pages.append(invoicePage(d,'КОПИЕ'));$('#previewNumber').textContent=d.number}
function archive(d){const record={...d,numericNumber:Number(d.number),createdAt:new Date().toISOString()};history=[record,...history.filter(x=>x.number!==record.number)].slice(0,100);setJSON(keys.history,history);$('#historyCount').textContent=history.length;if($('#rememberClient').checked){const clients=getJSON(keys.clients,[]);setJSON(keys.clients,[{name:d.clientName,id:d.clientId,mol:d.clientMol,address1:d.address1,address2:d.address2},...clients.filter(x=>x.id!==d.clientId)].slice(0,30))}}
function openPreview(){const d=values();archive(d);renderPreview(d);$('#previewDialog').showModal()}
function renderHistory(){const list=$('#historyList');if(!history.length){list.innerHTML='<div class="history-empty">Все още няма запазени фактури.</div>';return}list.innerHTML=history.map((x,i)=>`<div class="history-item"><div><b>№ ${x.number} · ${escapeHTML(x.clientName)}</b><small>${dateBG(x.date)} · ${money(x.total)}</small></div><span>${x.quantity} нощ.</span><button data-history="${i}">Отвори</button></div>`).join('');list.querySelectorAll('button').forEach(b=>b.onclick=()=>{renderPreview(history[+b.dataset.history]);$('#historyDialog').close();$('#previewDialog').showModal()})}
function escapeHTML(s=''){return s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function fillSupplier(){[['supplierName','name'],['supplierAddress','address'],['supplierCity','city'],['supplierCountry','country'],['supplierId','id'],['supplierMol','mol']].forEach(([id,k])=>$('#'+id).value=supplier[k])}
$('#invoiceForm').addEventListener('input',calculate);$('#invoiceForm').addEventListener('submit',e=>{e.preventDefault();openPreview()});
$('#resetButton').onclick=()=>{if(confirm('Да изчистя ли текущата чернова?')){localStorage.removeItem(keys.draft);$('#invoiceForm').reset();$('#date').value=new Date().toISOString().slice(0,10);$('#number').value=String((history[0]?.numericNumber||0)+1);$('#quantity').value=1;$('#price').value=60;$('#taxRate').value=.51;calculate()}};
$('#settingsButton').onclick=()=>{fillSupplier();$('#settingsDialog').showModal()};$('#historyButton').onclick=()=>{renderHistory();$('#historyDialog').showModal()};$('#backButton').onclick=()=>$('#previewDialog').close();
$('#supplierForm').onsubmit=e=>{e.preventDefault();supplier={name:$('#supplierName').value,address:$('#supplierAddress').value,city:$('#supplierCity').value,country:$('#supplierCountry').value,id:$('#supplierId').value,mol:$('#supplierMol').value};setJSON(keys.supplier,supplier);$('#settingsDialog').close()};
$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#printBoth').onclick=()=>{renderPreview(values());window.print()};$('#printOriginal').onclick=()=>{renderPreview(values(),true);window.print();setTimeout(()=>renderPreview(values()),500)};
$('#historyCount').textContent=history.length;loadDraft();
